import{_ as n}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as i,c as l,o as e,af as r,b as o,w as a,a as s,G as h,ag as b}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const k=JSON.parse('{"title":"站点边界与知识 ownership","description":"四站分工表——learn-ai / Learn LLM / evals / sites-epub 各自拥有什么、本仓保留什么、禁止复制什么；含 bridge 元数据规范与三站可访问性核验记录。","frontmatter":{"title":"站点边界与知识 ownership","description":"四站分工表——learn-ai / Learn LLM / evals / sites-epub 各自拥有什么、本仓保留什么、禁止复制什么；含 bridge 元数据规范与三站可访问性核验记录。","domain":"tech","tags":["tech","orientation","ownership"],"navOrder":2,"topicId":"site-boundaries","layer":"0","status":"canonical","nodeType":"boundary","owner":"learn-ai","externalOwners":[],"prerequisites":["tech-map"],"next":["model-lifecycle-bridge"],"specVersion":"","lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"zh/tech/00-map/site-boundaries.md","filePath":"zh/tech/00-map/site-boundaries.md","lastUpdated":1788326832000}'),c={name:"zh/tech/00-map/site-boundaries.md"};function g(p,t,u,E,A,f){const d=i("Mermaid");return e(),l("div",null,[t[1]||(t[1]=r('<blockquote><p><strong>所在组</strong>：层 0 · 方向与边界 ｜ <strong>上一组出口</strong>：无 ｜ <strong>本页出口</strong>：能判断一段知识该写在本仓还是跳转 sibling，并能写出合格的 bridge 链接 <strong>前置</strong>：<a href="./../index.html">技术地图</a> ｜ <strong>下一步</strong>：<a href="./../01-model-lifecycle/">模型生命周期（桥接）</a>——本页规则的第一个完整示范</p></blockquote><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p><strong>结论先讲</strong>：learn-ai 是跨技术主线的唯一 canonical，不是任何兄弟站的第二份拷贝。每个知识点只能有一个正文 owner；本仓遇到 sibling 已完整覆盖的主题时，只写「为什么它影响当前工程决策 + 停止点 + 下一跳」，禁止复制正文、完整推导、厂商长文或动态清单。</p><h3 id="心智模型-一个知识点-一个-owner" tabindex="-1">心智模型：一个知识点，一个 owner <a class="header-anchor" href="#心智模型-一个知识点-一个-owner" aria-label="Permalink to &quot;心智模型：一个知识点，一个 owner&quot;">​</a></h3>',4)),(e(),o(b,null,{default:a(()=>[h(d,{id:"mermaid-14",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20Q%5B%22%E6%9F%90%E4%B8%AA%E7%9F%A5%E8%AF%86%E7%82%B9%22%5D%20--%3E%20D%7B%E8%B0%81%E7%9A%84%E6%9C%80%E8%87%AA%E7%84%B6%20owner%3F%7D%0A%20%20%20%20D%20--%3E%7C%E8%B7%A8%E6%8A%80%E6%9C%AF%E4%B8%BB%E7%BA%BF%20%C2%B7%20%E5%86%B3%E7%AD%96%20%C2%B7%20%E5%AE%9E%E6%88%98%7C%20LA%5B%22learn-ai%3Cbr%2F%3E%E5%86%99%E4%BA%94%E6%AE%B5%E5%BC%8F%20canonical%22%5D%0A%20%20%20%20D%20--%3E%7C%E6%A8%A1%E5%9E%8B%E5%86%85%E9%83%A8%20%C2%B7%20%E8%AE%AD%E7%BB%83%E6%95%B0%E5%AD%A6%7C%20LLM%5B%22Learn%20LLM%3Cbr%2F%3E%E6%9C%AC%E4%BB%93%E5%8F%AA%E5%86%99%E6%A1%A5%E6%8E%A5%22%5D%0A%20%20%20%20D%20--%3E%7C%E8%AF%84%E4%BC%B0%E6%96%B9%E6%B3%95%20%C2%B7%20%E5%8F%91%E5%B8%83%E8%AF%81%E6%8D%AE%7C%20EV%5B%22evals%3Cbr%2F%3E%E6%9C%AC%E4%BB%93%E5%8F%AA%E5%86%99%E4%BD%95%E6%97%B6%E9%9C%80%E8%A6%81%22%5D%0A%20%20%20%20D%20--%3E%7C%E5%8E%82%E5%95%86%E5%8E%9F%E6%96%87%20%C2%B7%20EPUB%7C%20EP%5B%22sites-epub%3Cbr%2F%3E%E6%9C%AC%E4%BB%93%E5%8F%AA%E5%81%9A%E4%BA%8C%E6%AC%A1%E5%8A%A0%E5%B7%A5%22%5D%0A%20%20%20%20LA%20--%3E%20B%5B%22bridge%20%E7%99%BB%E8%AE%B0%EF%BC%9A%E5%81%9C%E6%AD%A2%E7%82%B9%20%2B%20canonicalUrl%20%2B%20retrievedAt%22%5D%0A%20%20%20%20LLM%20--%3E%20B%0A%20%20%20%20EV%20--%3E%20B%0A%20%20%20%20EP%20--%3E%20B%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[s(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=r('<h3 id="四站-ownership-表" tabindex="-1">四站 ownership 表 <a class="header-anchor" href="#四站-ownership-表" aria-label="Permalink to &quot;四站 ownership 表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Owner</th><th>拥有（canonical）</th><th>本仓保留</th><th>禁止复制</th></tr></thead><tbody><tr><td><strong>learn-ai</strong>（本仓）</td><td>跨技术主线、五段式章节、症状决策树、最小无密钥 fixture、调试 / 生产经验</td><td>—</td><td>不做任何 sibling 的第二 canonical</td></tr><tr><td><strong>Learn LLM</strong></td><td>模型内部机制、训练数学、底层 RAG / Agent 原理</td><td>决策影响 + 停止点 + deep-link</td><td>完整推导、训练实验细节</td></tr><tr><td><strong>evals</strong></td><td>评估方法、benchmark、scorer / judge、发布证据与评估流水线</td><td>何时需要证据 + 上线门如何接入</td><td>评估流水线实现、基准数据</td></tr><tr><td><strong>sites-epub</strong></td><td>厂商 docs / blog 原文捕获、EPUB 索引</td><td>跨厂商稳定概念的二次加工 + 阅读路线</td><td>厂商长文、动态命令 / 参数 / 套餐清单</td></tr></tbody></table><h3 id="决策表-一段内容写在哪" tabindex="-1">决策表：一段内容写在哪 <a class="header-anchor" href="#决策表-一段内容写在哪" aria-label="Permalink to &quot;决策表：一段内容写在哪&quot;">​</a></h3><table tabindex="0"><thead><tr><th>判断维度</th><th>写在本仓</th><th>跳转 sibling</th></tr></thead><tbody><tr><td>方向</td><td>影响工程决策的主线知识</td><td>深层原理与方法论</td></tr><tr><td>控制权</td><td>本仓作者能维护、能验收</td><td>由 sibling 作者与流水线维护</td></tr><tr><td>状态</td><td>稳定概念，随版本演进慢</td><td>动态数字（章节数、价格、模型清单）</td></tr><tr><td>信任域</td><td>本仓 reputation</td><td>sibling 的 canonical 地位</td></tr><tr><td>最低复杂度</td><td>一张 bridge 表 + 停止点</td><td>—</td></tr></tbody></table><p>历史版本里程碑：四站分工于 2026-09 随 Issue #116 冻结；此前「Learn LLM 章节互链」散落在各页，本页收拢为唯一 ownership 规则页。</p><h2 id="_2-使用" tabindex="-1">2. 使用 <a class="header-anchor" href="#_2-使用" aria-label="Permalink to &quot;2. 使用&quot;">​</a></h2><p>本页是规则页，无可运行代码产物；「使用」= bridge 链接演练（≤15 分钟，纸面即可）。验收标准：为三个真实主题各写出一条合格 bridge。</p><h3 id="每站的停止点与下一跳" tabindex="-1">每站的停止点与下一跳 <a class="header-anchor" href="#每站的停止点与下一跳" aria-label="Permalink to &quot;每站的停止点与下一跳&quot;">​</a></h3><p><strong>Learn LLM</strong>（<a href="https://llm.zenheart.site/%EF%BC%89" target="_blank" rel="noreferrer">https://llm.zenheart.site/）</a></p><ul><li>停止点示例：讲到「KV Cache 决定了上下文预算的量级」即停，不展开注意力复杂度推导。</li><li>下一跳格式：链接到具体章节路径（如 <code>https://llm.zenheart.site/chapters/09-inference-cache</code>），不是首页。</li></ul><p><strong>evals</strong>（<a href="https://evals.zenheart.site/%EF%BC%89" target="_blank" rel="noreferrer">https://evals.zenheart.site/）</a></p><ul><li>停止点示例：讲到「上线前需要可回放的证据」即停，不讲 judge 构建与基准设计。</li><li>下一跳格式：<code>https://evals.zenheart.site/book/</code> 下具体章节。</li></ul><p><strong>sites-epub</strong>（<a href="https://epub.zenheart.site/%EF%BC%89" target="_blank" rel="noreferrer">https://epub.zenheart.site/）</a></p><ul><li>停止点示例：讲到「该概念出自某厂商文档」即停，不复制厂商命令与参数。</li><li>下一跳格式：站点索引页；当前站点 HTTPS 不可达（见下方核验表），引用前必须复核。</li></ul><h3 id="演练-写一条合格-bridge" tabindex="-1">演练：写一条合格 bridge <a class="header-anchor" href="#演练-写一条合格-bridge" aria-label="Permalink to &quot;演练：写一条合格 bridge&quot;">​</a></h3><p>以「嵌入（embedding）的向量几何」为例：</p><ol><li><strong>判 owner</strong>：数学与训练目标 → Learn LLM。</li><li><strong>找 canonical 具体路径</strong>：<code>https://llm.zenheart.site/chapters/11-rag</code>（不是首页）。</li><li><strong>记 retrievedAt</strong>：2026-09-01，HTTP 200。</li><li><strong>写停止点与下一跳</strong>：「本仓讲到『嵌入把语义变成可比较的向量』为止；空间几何与训练目标见 Learn LLM 第 11 章。」</li></ol><p><strong>负例</strong>：只写「详见 Learn LLM」并链接首页——读者无法验证目标章节是否存在，也无法判断内容何时过期。</p><h3 id="站点可访问性核验表" tabindex="-1">站点可访问性核验表 <a class="header-anchor" href="#站点可访问性核验表" aria-label="Permalink to &quot;站点可访问性核验表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>站点</th><th>URL</th><th>状态</th><th>retrievedAt</th></tr></thead><tbody><tr><td>Learn LLM</td><td><a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">https://llm.zenheart.site/</a></td><td>HTTP 200，正常</td><td>2026-09-01</td></tr><tr><td>Learn LLM 章节目录</td><td><a href="https://llm.zenheart.site/chapters/" target="_blank" rel="noreferrer">https://llm.zenheart.site/chapters/</a></td><td>HTTP 200，21 章地图可读</td><td>2026-09-01</td></tr><tr><td>evals</td><td><a href="https://evals.zenheart.site/" target="_blank" rel="noreferrer">https://evals.zenheart.site/</a></td><td>HTTP 200，正常</td><td>2026-09-01</td></tr><tr><td>evals 阅读入口</td><td><a href="https://evals.zenheart.site/book/" target="_blank" rel="noreferrer">https://evals.zenheart.site/book/</a></td><td>HTTP 200</td><td>2026-09-01</td></tr><tr><td>sites-epub</td><td><a href="https://epub.zenheart.site/" target="_blank" rel="noreferrer">https://epub.zenheart.site/</a></td><td><strong>warning</strong>：TLS 证书不匹配（返回 <code>*.github.com</code> 证书），HTTPS 当前不可达</td><td>2026-09-01</td></tr></tbody></table><p>sites-epub 的所有权声明继续有效（见 <code>_phase0/bridge-register.md</code>），但引用其内容前必须先复核站点恢复情况；本仓不基于不可达站点写死任何内容断言。</p><h2 id="_3-原理" tabindex="-1">3. 原理 <a class="header-anchor" href="#_3-原理" aria-label="Permalink to &quot;3. 原理&quot;">​</a></h2><h3 id="为什么一个知识点只能有一个-owner" tabindex="-1">为什么一个知识点只能有一个 owner <a class="header-anchor" href="#为什么一个知识点只能有一个-owner" aria-label="Permalink to &quot;为什么一个知识点只能有一个 owner&quot;">​</a></h3><p>复制正文的问题不是存储成本，而是<strong>漂移成本</strong>：sibling 更新后，本仓副本静默过期；读者看到两个版本，无法判断哪个可信；审计需要双倍核对。SSOT（single source of truth，单一事实源）原则把复制替换为<strong>可验证的指针</strong>：canonicalUrl + retrievedAt + 停止点。</p><h3 id="为什么动态数字不进本仓" tabindex="-1">为什么动态数字不进本仓 <a class="header-anchor" href="#为什么动态数字不进本仓" aria-label="Permalink to &quot;为什么动态数字不进本仓&quot;">​</a></h3><p>章节数、价格、可用性、模型清单都会变。静态复制它们等于在本仓埋定时过期数据。规则：这类事实只记 URL 与 retrievedAt，正文写稳定结论（「以站点当前为准」）。</p><h3 id="bridge-元数据字段" tabindex="-1">bridge 元数据字段 <a class="header-anchor" href="#bridge-元数据字段" aria-label="Permalink to &quot;bridge 元数据字段&quot;">​</a></h3><p>每条跨站跳转至少记录：</p><table tabindex="0"><thead><tr><th>字段</th><th>含义</th><th>示例</th></tr></thead><tbody><tr><td>canonicalTopicId</td><td>本仓侧主题 ID</td><td><code>context</code></td></tr><tr><td>owner</td><td>深层内容的 canonical 站点</td><td>Learn LLM</td></tr><tr><td>停止点（stop point）</td><td>本仓正文到哪里为止</td><td>「KV Cache 限制上下文预算」</td></tr><tr><td>canonicalUrl</td><td>目标的具体路径（非首页）</td><td><code>https://llm.zenheart.site/chapters/09-inference-cache</code></td></tr><tr><td>sourceCommitOrVersion</td><td>目标内容版本（可得时）</td><td>章节修订号；不可得写「未提供」</td></tr><tr><td>prerequisites / nextQuestion</td><td>读者跳转前后的问题</td><td>「为什么上下文有预算」/「如何压缩上下文」</td></tr><tr><td>lastVerified / retrievedAt</td><td>最近核验日期</td><td>2026-09-01</td></tr></tbody></table><p>完整登记表在仓库内 <code>_phase0/bridge-register.md</code> 维护（工程工件，不随站点发布）；对外页面只携带表中的 URL 与停止点。</p><h3 id="规范要求-vs-本地实测" tabindex="-1">规范要求 vs 本地实测 <a class="header-anchor" href="#规范要求-vs-本地实测" aria-label="Permalink to &quot;规范要求 vs 本地实测&quot;">​</a></h3><p>本页无协议规范。站点状态的「本地实测」即上方核验表；复核命令为对目标 URL 发起一次 HTTPS 请求并确认 200 与证书有效。</p><h2 id="_4-开发" tabindex="-1">4. 开发 <a class="header-anchor" href="#_4-开发" aria-label="Permalink to &quot;4. 开发&quot;">​</a></h2><p>本页无代码集成；「开发」= ownership 冲突与链接失效的处置 runbook。</p><h3 id="症状-→-证据-→-处理-→-完成标准" tabindex="-1">症状 → 证据 → 处理 → 完成标准 <a class="header-anchor" href="#症状-→-证据-→-处理-→-完成标准" aria-label="Permalink to &quot;症状 → 证据 → 处理 → 完成标准&quot;">​</a></h3><p><strong>症状</strong>：同一主题在本仓与 sibling（或本仓两页）出现两份正文。 <strong>证据</strong>：内容审计发现重复论述；或两处版本说法不一致。 <strong>处理</strong>：判定 canonical owner——主线决策归本仓、深层原理归 sibling；败方改为 bridge（保留停止点 + 下一跳）或 redirect。 <strong>完成标准</strong>：该主题只剩一个 topicId、一份正文；bridge 登记表与 redirects.json 同步更新。</p><h3 id="症状-→-证据-→-处理-→-完成标准-1" tabindex="-1">症状 → 证据 → 处理 → 完成标准 <a class="header-anchor" href="#症状-→-证据-→-处理-→-完成标准-1" aria-label="Permalink to &quot;症状 → 证据 → 处理 → 完成标准&quot;">​</a></h3><p><strong>症状</strong>：资料库里的 sibling 深链 404 或内容对不上。 <strong>证据</strong>：retrievedAt 已超过一个季度；请求返回非 200。 <strong>处理</strong>：到 sibling 站点重新定位 canonical 路径，更新 canonicalUrl 与 retrievedAt；找不到等价内容时降级为首页链接并标注「具体章节未定位」。 <strong>完成标准</strong>：链接恢复 200 且锚点内容仍支持原断言。</p><h3 id="症状-→-证据-→-处理-→-完成标准-2" tabindex="-1">症状 → 证据 → 处理 → 完成标准 <a class="header-anchor" href="#症状-→-证据-→-处理-→-完成标准-2" aria-label="Permalink to &quot;症状 → 证据 → 处理 → 完成标准&quot;">​</a></h3><p><strong>症状</strong>：sibling 站点整体不可达（当前 sites-epub 的实况）。 <strong>证据</strong>：HTTPS 请求失败或证书不匹配。 <strong>处理</strong>：在涉及页面标注 warning 与 retrievedAt，不删除所有权记录，不基于该站新增内容断言。 <strong>完成标准</strong>：站点恢复 200 后更新状态行；期间新增引用为零。</p><h3 id="反模式清单" tabindex="-1">反模式清单 <a class="header-anchor" href="#反模式清单" aria-label="Permalink to &quot;反模式清单&quot;">​</a></h3><ul><li>「详见某站」+ 首页链接：不可验证、不可审计的桥。</li><li>把 sibling 章节翻译 / 摘要进本仓：制造第二 canonical。</li><li>静态复制动态数字（章节数、价格、模型列表）：埋定时过期数据。</li></ul><h2 id="_5-资料库" tabindex="-1">5. 资料库 <a class="header-anchor" href="#_5-资料库" aria-label="Permalink to &quot;5. 资料库&quot;">​</a></h2><p>四级阅读路线：</p><ul><li><strong>Beginner</strong>：读本页四站表；能判断「这段内容该写哪」。</li><li><strong>Builder</strong>：写第一条合格 bridge（见「使用」演练），并被复核。</li><li><strong>Operator</strong>：维护一个主题簇的 bridge 登记，季度复核 retrievedAt。</li><li><strong>Researcher</strong>：通读 sibling 站点结构，理解各自的知识定位。</li></ul><h3 id="资源表" tabindex="-1">资源表 <a class="header-anchor" href="#资源表" aria-label="Permalink to &quot;资源表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>证据层级</th><th>canonical URL</th><th>用途</th><th>支持的断言</th><th>下一步</th></tr></thead><tbody><tr><td>Learn LLM</td><td>sibling</td><td><a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">https://llm.zenheart.site/</a></td><td>模型内部机制的 canonical</td><td>深层原理归该站（retrievedAt 2026-09-01，HTTP 200）</td><td><a href="https://llm.zenheart.site/chapters/" target="_blank" rel="noreferrer">章节目录</a></td></tr><tr><td>evals</td><td>sibling</td><td><a href="https://evals.zenheart.site/" target="_blank" rel="noreferrer">https://evals.zenheart.site/</a></td><td>评估方法论的 canonical</td><td>评估归该站（retrievedAt 2026-09-01，HTTP 200）</td><td><a href="https://evals.zenheart.site/book/" target="_blank" rel="noreferrer">阅读入口</a></td></tr><tr><td>evals 源码仓</td><td>sibling</td><td><a href="https://github.com/zenHeart/evals" target="_blank" rel="noreferrer">https://github.com/zenHeart/evals</a></td><td>评估站的内容来源</td><td>仓站对应关系（retrievedAt 2026-09-01，HTTP 200）</td><td>—</td></tr><tr><td>sites-epub</td><td>sibling</td><td><a href="https://epub.zenheart.site/" target="_blank" rel="noreferrer">https://epub.zenheart.site/</a></td><td>厂商原文与 EPUB 的 canonical</td><td>所有权声明有效但站点当前不可达（retrievedAt 2026-09-01，warning）</td><td>恢复后复核</td></tr></tbody></table><h3 id="主动证伪与未决问题" tabindex="-1">主动证伪与未决问题 <a class="header-anchor" href="#主动证伪与未决问题" aria-label="Permalink to &quot;主动证伪与未决问题&quot;">​</a></h3><ul><li>证伪入口：如果你发现某个 sibling 已完整覆盖的主题在本仓存在长正文（而非 bridge），本页规则被执行失败，应立案迁移而不是补充。</li><li>未决：sites-epub HTTPS 恢复时间未知；期间所有依赖该站的阅读路线都以 Learn LLM / evals 为替代入口。</li><li>未决：<code>sourceCommitOrVersion</code> 字段在多数 sibling 页面不可得，统一记「未提供」，待 sibling 提供稳定版本标识后升级。</li></ul><h3 id="learn-ai-到此为止-继续去哪" tabindex="-1">learn-ai 到此为止 / 继续去哪 <a class="header-anchor" href="#learn-ai-到此为止-继续去哪" aria-label="Permalink to &quot;learn-ai 到此为止 / 继续去哪&quot;">​</a></h3><ul><li>本仓下一个示范：<a href="./../01-model-lifecycle/">模型生命周期（桥接）</a>——按本页规则写成的完整 bridge 页。</li><li>模型深层原理：<a href="https://llm.zenheart.site/chapters/" target="_blank" rel="noreferrer">Learn LLM</a>。</li><li>评估方法论：<a href="https://evals.zenheart.site/" target="_blank" rel="noreferrer">evals</a>。</li></ul><h2 id="资料库证据层级-全树-legend" tabindex="-1">资料库证据层级（全树 legend） <a class="header-anchor" href="#资料库证据层级-全树-legend" aria-label="Permalink to &quot;资料库证据层级（全树 legend）&quot;">​</a></h2><p>各页资料库的「层级」列使用统一字母，定义如下（个别历史页的标注存在 ±1 漂移，以本表为准）：</p><table tabindex="0"><thead><tr><th>层级</th><th>含义</th><th>典型来源</th></tr></thead><tbody><tr><td>E</td><td>本地实证</td><td>本仓可运行的 fixture 实测输出</td></tr><tr><td>L0</td><td>官方规范 / 一手实现</td><td>协议规范、SDK 源码、CHANGELOG</td></tr><tr><td>L1</td><td>官方维护者叙述</td><td>官方文档、官方工程博客</td></tr><tr><td>L2</td><td>权威二次加工</td><td>知名工程书、系统综述</td></tr><tr><td>L4</td><td>背景线索</td><td>社区讨论、未署名文章（仅作线索）</td></tr><tr><td>sibling</td><td>姊妹站 canonical</td><td>Learn LLM / evals / sites-epub</td></tr></tbody></table>',54))])}const q=n(c,[["render",g]]);export{k as __pageData,q as default};
